  Notation D2D l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16) (only parsing).

  Notation HEAD5 pc mm k pt bits t1 a1 a7 x8 x9 x18 x19 x20 x21 :=
    (MS (mkR ra (Z_to_bv 64 (SP + -48)) gp tp (Z_to_bv 64 pt) t1 (Z_to_bv 64 (64 - tl)) x8 x9 (Z_to_bv 64 (DST + k)) a1
             (Z_to_bv 64 SS) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 bits) a7
             x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 67064) (Z_to_bv 64 (DST + dcap - 9)) (Z_to_bv 64 8) (Z_to_bv 64 64))
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).
  Notation HEAD4 pc mm k pt bits t1 a1 a7 x8 x9 x18 x19 x20 x21 :=
    (MS (mkR ra (Z_to_bv 64 (SP + -48)) gp tp (Z_to_bv 64 pt) t1 (Z_to_bv 64 (64 - tl)) x8 x9 (Z_to_bv 64 (DST + k)) a1
             (Z_to_bv 64 SS) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 bits) a7
             x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 67064) (Z_to_bv 64 (DST + dcap - 7)) (Z_to_bv 64 8) (Z_to_bv 64 64))
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  (* [comment removed for export] *)
  Ltac x2cell v :=
    lazymatch goal with |- context [Z_to_bv 64 (((bv_unsigned ?c ≪ ?b) mod 18446744073709551616) ≫ ?sh)] =>
      let EV := fresh "EV" in let VR := fresh "VR" in
      remember (((bv_unsigned c ≪ b) mod 18446744073709551616) ≫ sh) as v eqn:EV;
      assert (VR : 0 <= v < 2^tl)
        by (subst v; apply (D2 x2_idx_bound); [apply bv_unsigned_in_range| first [reflexivity | apply Z.mod_small; lia | lia]]);
      clear EV end.

  Ltac x2rd v c EC :=
    lazymatch goal with CE : bytes_at psegs ?mm (DT + 4) cbs, SQ : 0 <= x2_seq c < 65536 |- _ =>
      let RC0 := fresh "RC" in let RC2 := fresh "RC" in let RC3 := fresh "RC" in let RCB := fresh "RC" in
      destruct (x2_cell_rd psegs mm (DT + 4) cells (Z.to_nat (4 * 2^tl)) v c ltac:(rewrite <- ECB; exact CE)
                  ltac:(lia) ltac:(lia) ltac:(lia) EC SQ) as (RC0 & RC2 & RC3 & RCB) end.

  Ltac x2c v c EC :=
    lazymatch goal with TCK : forall i, 0 <= i < 2^tl -> _, VR : 0 <= v < 2^tl |- _ =>
      remember (nth (Z.to_nat v) cells x2_default) as c eqn:EC;
      let SQ := fresh "SQ" in let NB := fresh "NB" in let LN := fresh "LN" in
      destruct (TCK v VR) as (SQ & NB & LN); rewrite <- EC in SQ, NB, LN end.

  (* [comment removed for export] *)
  Ltac x2d OUT v c EC i padd :=
    zstep; zstep; x2cell v;
    zstep; zstep; rewrite (Z.shiftl_mul_pow2 v 2) by lia; change (2^2) with 4; replace (v * 4) with (4 * v) by ring;
    x2c v c EC; x2rd v c EC;
    zstep; (lazymatch padd with true => zstep | false => idtac end);
    zstep; unfold sx16;
    u8_sok OUT i; zstep; u8_store_same OUT i;
    u8_sok OUT (i + 1); zstep; u8_store_same OUT (i + 1);
    x2rd v c EC;
    zstep; zstep; rewrite ?(byte_lit (x2_nbBits c)), ?(byte_lit (x2_len c)) by lia;
    zstep.


  (* [comment removed for export] *)
  Definition ENT (buf : list Z) : Prop :=
    u8arr psegs m0 DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap
    /\ bytes_at psegs m0 SS (map (Z_to_bv 8) src) /\ bytes_at psegs m0 (DT + 4) cbs
    /\ bytes_at psegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl]
    /\ stk psegs m0 lo SP /\ mem_inv psegs m0.

